from __future__ import annotations

from reduction.grammar import Grammar, RuleType
from reduction.parser import Parser
from reduction.property_test import PropertyTester
from reduction.reducer import AbstractReducer
from reduction.tree import SparTreeNode
from reduction.tree_utils import iter_nodes, node_at


class LocalExhaustiveReducer(AbstractReducer):
    """Try every non-empty deletion pattern inside a small sliding window."""

    def __init__(self, grammar: Grammar, window_size: int = 3, max_tests: int = 200):
        self.grammar = grammar
        self.parser = Parser(grammar)
        self.window_size = max(1, window_size)
        self.max_tests = max(1, max_tests)

    @property
    def name(self) -> str:
        return "vulcan_local_exhaustive"

    def reduce(self, tree: SparTreeNode, tester: PropertyTester) -> SparTreeNode:
        working = tree.clone()
        start_tests = tester.test_count

        while tester.test_count - start_tests < self.max_tests:
            deletable = self._collect_deletable_nodes(working)
            if not deletable:
                return working

            changed = False
            for start in range(len(deletable)):
                window = deletable[start:start + self.window_size]
                if not window:
                    continue
                for mask in range(1, 1 << len(window)):
                    if tester.test_count - start_tests >= self.max_tests:
                        return working
                    chosen = [
                        window[index]
                        for index in range(len(window))
                        if mask & (1 << index)
                    ]
                    if not self._can_delete(working, chosen):
                        continue
                    candidate = working.clone()
                    for parent_path, child_index in chosen:
                        parent = node_at(candidate, parent_path)
                        if parent is None:
                            continue
                        parent.children[child_index].delete()
                    candidate_source = candidate.to_source()
                    if tester.test(candidate_source):
                        working = self.parser.parse(candidate_source)
                        changed = True
                        break
