        deletable: list[tuple[tuple[int, ...], int]] = []
        for path, node in iter_nodes(tree):
            rule = self.grammar.expected_rule(node.rule_name)
            if rule is None or rule.rule_type not in (RuleType.KLEENE_STAR, RuleType.KLEENE_PLUS):
                continue
            minimum = 1 if rule.rule_type == RuleType.KLEENE_PLUS else 0
            active_indexes = [
                index
                for index, child in enumerate(node.children)
                if not child.deleted
